const inputData = $input.first().json;
const tenantId = inputData.tenant_id;
const phone = inputData.phone;

const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!tenantId || typeof tenantId !== 'string' || !uuidRegex.test(tenantId.trim())) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_TENANT_ID",
      message: "O parâmetro 'tenant_id' é obrigatório e deve ser um UUID válido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!phone || typeof phone !== 'string' || phone.trim().length < 8) {
  return [{
    json: {
      is_valid: false,
      status: "validation_error",
      code: "INVALID_PHONE",
      message: "O parâmetro 'phone' é obrigatório e deve conter pelo menos 8 dígitos (ex: '+5511999999999')",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: tenantId.trim(),
    phone: phone.trim()
  }
}];

const items = $input.all();
const first = items[0];

if (first.error) {
  return [{
    json: {
      status: "error",
      code: "DB_QUERY_ERROR",
      message: "Erro ao consultar contato no PostgreSQL",
      error_details: first.error.message || "Erro desconhecido",
      timestamp: new Date().toISOString()
    }
  }];
}

if (items.length === 0 || !first.json || !first.json.contact_id) {
  return [{
    json: {
      status: "success",
      code: "NOT_FOUND",
      found: false,
      message: "Contato não encontrado para o tenant e telefone informados",
      contact: null,
      timestamp: new Date().toISOString()
    }
  }];
}

const contact = first.json;
return [{
  json: {
    status: "success",
    code: "CONTACT_FOUND",
    found: true,
    message: "Contato localizado com sucesso",
    contact: {
      contact_id: contact.contact_id,
      tenant_id: contact.tenant_id,
      name: contact.name,
      email: contact.email || null,
      phone: contact.phone,
      status: contact.status,
      metadata: contact.metadata || {},
      created_at: contact.created_at
    },
    timestamp: new Date().toISOString()
  }
}];
